// Some portions generated by Codex
package org.eclipse.rdf4j.repository.manager;

import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.text.Normalizer;
import java.util.Locale;
import java.util.Set;

import org.eclipse.rdf4j.repository.config.RepositoryConfigException;

/**
 * Validates repository identifiers before {@link LocalRepositoryManager} uses them as filesystem path components.
 */
final class RepositoryIdValidator {
	private static final Set<String> WINDOWS_RESERVED_NAMES = Set.of(
			"CON", "CONIN$", "CONOUT$", "PRN", "AUX", "NUL",
			"COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
			"LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9");

	private RepositoryIdValidator() {
	}

	static void validate(String repositoryId) throws RepositoryConfigException {
		if (repositoryId == null) {
			throw new RepositoryConfigException("Repository ID missing");
		}
		if (repositoryId.isBlank()) {
			throw invalid("must not be blank");
		}
		if (".".equals(repositoryId) || "..".equals(repositoryId)) {
			throw invalid("must not be a dot segment");
		}
		if (repositoryId.indexOf('/') >= 0 || repositoryId.indexOf('\\') >= 0) {
			throw invalid("must not contain path separators");
		}
		if (containsEncodedPathSyntax(repositoryId)) {
			throw invalid("must not contain percent-encoded path syntax");
		}
		if (repositoryId.codePoints().anyMatch(Character::isISOControl)) {
			throw invalid("must not contain control characters");
		}
		if (!Normalizer.isNormalized(repositoryId, Normalizer.Form.NFC)) {
			throw invalid("must use canonical Unicode normalization");
		}
		String compatibilityForm = Normalizer.normalize(repositoryId, Normalizer.Form.NFKC);
		if (containsPathSyntax(compatibilityForm) || containsUnicodeSeparator(repositoryId)) {
			throw invalid("must not contain ambiguous Unicode path characters");
		}
		if (hasInvalidWindowsForm(repositoryId) || hasInvalidWindowsForm(compatibilityForm)) {
			throw invalid("must be a portable path component");
		}

		try {
			Path path = Path.of(repositoryId);
			if (path.isAbsolute() || path.getNameCount() != 1) {
				throw invalid("must be one relative path component");
			}
		} catch (InvalidPathException e) {
			throw new RepositoryConfigException("Repository ID is not a valid path component", e);
		}
	}

	static Path resolveRepositoryDirectory(Path repositoriesDirectory, String repositoryId) {
		validate(repositoryId);
		Path normalizedRoot = repositoriesDirectory.toAbsolutePath().normalize();
		Path candidate = normalizedRoot.resolve(repositoryId).normalize();
		if (!normalizedRoot.equals(candidate.getParent())) {
			throw invalid("resolves outside the repositories directory");
		}
		return candidate;
	}

	private static boolean hasWindowsDrivePrefix(String repositoryId) {
		return repositoryId.length() >= 2 && Character.isLetter(repositoryId.charAt(0))
				&& repositoryId.charAt(1) == ':';
	}

	private static boolean containsPathSyntax(String repositoryId) {
		return ".".equals(repositoryId) || "..".equals(repositoryId)
				|| repositoryId.indexOf('/') >= 0 || repositoryId.indexOf('\\') >= 0
				|| hasWindowsDrivePrefix(repositoryId);
	}

	private static boolean containsUnicodeSeparator(String repositoryId) {
		return repositoryId.codePoints()
				.anyMatch(codePoint -> codePoint == 0x2044 || codePoint == 0x2215
						|| codePoint == 0x29f5 || codePoint == 0x29f8 || codePoint == 0x29f9
						|| codePoint == 0xfe68);
	}

	private static boolean containsEncodedPathSyntax(String repositoryId) {
		String lower = repositoryId.toLowerCase(Locale.ROOT);
		return lower.contains("%00") || lower.contains("%2e") || lower.contains("%2f") || lower.contains("%5c");
	}

	private static boolean hasInvalidWindowsForm(String repositoryId) {
		if (repositoryId.endsWith(".") || repositoryId.endsWith(" ")
				|| repositoryId.chars().anyMatch(character -> "<>:\"|?*".indexOf(character) >= 0)) {
			return true;
		}
		String baseName = repositoryId;
		int extension = repositoryId.indexOf('.');
		if (extension >= 0) {
			baseName = repositoryId.substring(0, extension);
		}
		return WINDOWS_RESERVED_NAMES.contains(baseName.toUpperCase(Locale.ROOT));
	}

	private static RepositoryConfigException invalid(String detail) {
		return new RepositoryConfigException("Repository ID " + detail);
	}
}
